import sys, json, re, hashlib, datetime

# THE PUSH OF THE OBJECTS HIVE (GH #951, O.4/O.6). Events only, no clock: a
# new version of an active row (`changed` from `./gate`: a promotion, a tool
# write, a sighting) is announced to the graph space (`source_changed`) and
# memory is asked for the facts about the object (`facts`, memory's `in_query
# {subject}` in the row's round). The facts come back on `in_facts`; then the
# brief is rendered (`./brief`) and pushed to the curator as a `candidate`
# (triggers = the aliases, round = the row's round), and the aliases go to
# memory as `alias` (all aliases -> the object id).
#
# A PUSH ONLY ON NEWS. `pushes` holds, per object, the hash of the last pushed
# brief (canonical row + facts) and of the last pushed alias set. The same
# `in_facts` twice pushes nothing the second time; an `alias_ack` causes an
# `alias` only to send a spelling memory refused `store_refused` again, at most
# twice (M: `canonicalize` runs over all facts, a loop would be costly).
# The hashes are written FIRST (compare-and-set on the old hashes) and the
# candidate / alias leave only when that write won -- two pushes of one
# version cannot both go out.
#
# Aliases in memory are roundless -- they reveal an id, never content: the
# brief travels only with the row's round (`hop.audience_set`), and the
# curator delivers it only to a turn of a covered round (K.1).
#
# A retired active row withdraws its candidate (`withdraw`) and tombs its
# source; its hashes are reset, so that a row made active again is pushed anew.
# Two rows with the same alias (two rounds): memory keeps the alias on the
# oldest active one and answers `alias_taken` for the younger -- expected,
# parked without a word.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
h = (doc.get("envelope") or {}).get("header") or {}
hop = h.get("hop") or {}
ctx = h.get("context") or {}

ME = "push"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
SLOTS = ("what", "where", "who", "when", "why", "how")
ID_RE = re.compile(r"^ob-[0-9a-f]{12}$")
COLS = ["id", "rev", "type", "aliases", "state", "origin", "valid_since", "audience_set",
        "slots", "refs", "seen", "turns", "supersedes", "recorded_at"]
FACTS_LIMIT = 3
FACT_CHARS = 200
TRIGGER_MAX = 64
TRIGGERS_MAX = 16
ALIASES_MAX = 32
# OR-BC-75 (memory as built): how often an alias refused `store_refused` is
# sent again; the round rides in `alias_tag` as `<id>#r<n>`.
ALIAS_RETRIES = 2


def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def loads(v, default):
    if isinstance(v, str):
        try:
            x = json.loads(v)
        except Exception:
            return default
        return x if isinstance(x, type(default)) else default
    return v if isinstance(v, type(default)) else default


def v12(oid, rev):
    return hashlib.sha256(("%s:%d" % (oid, int(rev))).encode("utf-8")).hexdigest()[:12]


def sha(v):
    return hashlib.sha256(json.dumps(v, sort_keys=True, ensure_ascii=False,
                                     separators=(",", ":")).encode("utf-8")).hexdigest()[:16]


# --8<-- object-graph
# The nodes and edges of one object row, ONE definition in two cells: `./source`
# answers `outline`/`links` with them and `./push` announces their counts on
# `source_changed`; `gh951_the_brief_is_deterministic_and_round_bound.rs` holds
# the two copies to one text. Root node anchor '' (the object), one node per
# filled slot `slot:<name>`; `who` shows as `<n> people`. Edges, all
# `extracted`: `owner` per person reference in `who`, `doc` per document
# address, `related` per object address.
def _one(v):
    return " ".join(str(v or "").split())


def object_nodes(row):
    slots = loads(row.get("slots"), {})
    aliases = [a for a in loads(row.get("aliases"), []) if isinstance(a, str) and a]
    name = aliases[0] if aliases else str(row.get("id") or "")
    what = _one(slots.get("what"))
    out = [{"anchor": "", "kind": "object", "name": name,
            "oneline": ("%s: %s" % (_one(row.get("type")), what or name))[:300],
            "parser": "objects"}]
    for s in SLOTS:
        v = slots.get(s)
        if s == "who":
            n = len([x for x in v if isinstance(x, str) and x]) if isinstance(v, list) else 0
            line = "%d people" % n if n else ""
        else:
            line = _one(v) if isinstance(v, str) else ""
        if line:
            out.append({"anchor": "slot:" + s, "kind": "slot", "name": s,
                        "oneline": line[:300], "parser": "objects"})
    return out


def object_links(row):
    slots = loads(row.get("slots"), {})
    refs = loads(row.get("refs"), {})
    out = []
    for kind, targets in (("owner", slots.get("who")), ("doc", refs.get("doc")),
                          ("related", refs.get("related"))):
        for t in targets if isinstance(targets, list) else []:
            if isinstance(t, str) and t:
                out.append({"kind": kind, "from_anchor": "", "target_name": t,
                            "class": "extracted"})
    return out
# --8<-- end object-graph


def aliases_of(row):
    return [a for a in loads(row.get("aliases"), []) if isinstance(a, str) and a]


def canonical(row):
    """What a brief and a candidate depend on -- not `rev`, `seen`, `turns` or
    a timestamp, so a sighting that changes none of it pushes nothing."""
    return {"id": row.get("id"), "type": row.get("type"), "aliases": aliases_of(row),
            "state": row.get("state"), "audience_set": row.get("audience_set"),
            "slots": loads(row.get("slots"), {}), "refs": loads(row.get("refs"), {})}


def brief_hash(row, facts):
    return sha({"row": canonical(row), "facts": facts})


def alias_hash(row):
    return sha({"id": row.get("id"), "aliases": aliases_of(row)})


def fact_text(f):
    """One fact of memory's answer as the brief shows it: its predicate in
    front of its text when it has one. The subject is the object's own id and
    says nothing to a reader; a claim without its predicate ("blue") does not
    say which question it answers."""
    if not isinstance(f, dict) or f.get("kind", "fact") != "fact":
        return ""
    text = " ".join(str(f.get("text") or "").split())
    if not text:
        return ""
    pred = " ".join(str(f.get("predicate") or "").split())
    return "%s: %s" % (pred, text) if pred else text


def bundle_of(body):
    """The answer of memory's `in_query {subject}` (GH #948): a JSON text in
    `system.memory.bundle.text`, `{subject, as_of, answers, candidates[],
    complete, complete_reason?}`. Anything else reads as no answer."""
    b = loads((((body.get("system") or {}).get("memory") or {}).get("bundle") or {})
              .get("text"), {})
    return b if isinstance(b.get("candidates"), list) else None


def facts_of(bundle):
    """The texts of at most FACTS_LIMIT facts of the answer, in its own order
    (memory answers newest first). One reading only: the bundle's
    `candidates[]` -- its rendered text turn is for a model, not for this cell."""
    out = []
    for f in bundle.get("candidates") or []:
        t = fact_text(f)[:FACT_CHARS]
        if t and t not in out:
            out.append(t)
        if len(out) >= FACTS_LIMIT:
            break
    return out


def announce(row):
    return {"header": {"route": "source_changed"},
            "source": row["id"], "version": v12(row["id"], row["rev"]), "path": "",
            "fmt": "object", "parser": "objects", "mark": "",
            "nodes": len(object_nodes(row)), "links": len(object_links(row)), "tomb": False,
            "audience_set": str(row.get("audience_set") or "")}


def ask_facts(row):
    # Memory's `in_query {subject}` (GH #948) takes the body `{subject, limit,
    # messages}`; the member's door stamps the round (`audience_now`) and
    # `recall_caller` into the context and nothing else.
    return {"header": {"route": "facts", "audience_now": str(row.get("audience_set") or ""),
                       "subject": row["id"], "recall_caller": "objects"},
            "subject": row["id"], "limit": FACTS_LIMIT, "messages": []}


def candidate(row, text):
    triggers = [a for a in aliases_of(row) if len(a) <= TRIGGER_MAX][:TRIGGERS_MAX]
    return {"header": {"route": "candidate", "audience_set": str(row.get("audience_set") or "")},
            "source": "objects",
            "candidates": [{"id": row["id"], "text": text, "triggers": triggers, "once": False}]}


def alias_msgs(row):
    # Memory's `in_alias` (GH #948): `messages: []` is part of its body;
    # `alias_tag` comes back on `alias_ack` and names the object in a log line.
    # Memory takes at most ALIASES_MAX aliases per message (GH #951, review of
    # the seam): a longer set goes out in pieces of ALIASES_MAX, in order, one
    # `alias` each -- cut at ALIASES_MAX, the rest of the names would never
    # reach memory. No alias at all: no message (memory wants 1..ALIASES_MAX).
    pairs = [{"alias": a, "canonical": row["id"]} for a in aliases_of(row)]
    return [{"header": {"route": "alias", "alias_tag": row["id"]},
             "aliases": pairs[i:i + ALIASES_MAX], "force": False, "messages": []}
            for i in range(0, len(pairs), ALIASES_MAX)]


def emit(msgs):
    for m in msgs:
        if isinstance(m, dict) and "messages" not in m:
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs, ensure_ascii=False))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("objects/push: %s\n" % reason)
    emit([])


def store(ops, phase, carry):
    return {"header": {"route": "push_store", "phase": phase, "reply_cell": ME,
                       "cur_call": json.dumps(carry, sort_keys=True, ensure_ascii=False)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(a, ensure_ascii=False)} for cid, a in ops]}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": "", "rows": 0}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": "", "rows": 0})
                leg["error_code"] = str(r.get("error_code") or "")
                leg["rows"] = int(r.get("rows_affected") or 0)
    elif len(out) == 1:
        leg = next(iter(out.values()))
        leg["error_code"] = str(hop.get("error_code") or "")
        leg["rows"] = int(hop.get("rows_affected") or 0)
    return out


def rows_of(leg):
    p = (leg or {}).get("payload")
    return [r for r in p if isinstance(r, dict)] if isinstance(p, list) else []


lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")

if lane == "changed":
    row = d.get("row") if isinstance(d.get("row"), dict) else {}
    if not ID_RE.match(str(row.get("id") or "")):
        park("changed without a row -- dropped")
    if row.get("state") == "active":
        emit([announce(row), ask_facts(row)])
    if row.get("state") == "retired" and d.get("prev_state") == "active":
        aud = str(row.get("audience_set") or "")
        emit([{"header": {"route": "candidate", "audience_set": aud},
               "source": "objects", "candidates": [], "withdraw": [row["id"]]},
              {"header": {"route": "source_changed"},
               "source": row["id"], "path": "", "tomb": True, "audience_set": aud},
              store([("r", {"operation": "update", "table": "pushes",
                            "set": {"brief_hash": "", "alias_hash": "", "at": now()},
                            "where": {"id": row["id"]}})], "reset", {"id": row["id"]})])
    park()

if lane == "in_facts":
    bundle = bundle_of(d)
    # The subject is the one ASKED (review O I-2): the member's `facts` door
    # keeps the id in `context.objects_subject`, and both ways back (bundle and
    # refusal) restate it as `hop.subject`. Nothing in the answer names the row
    # it lands on -- a bundle's own `subject` that differs (a canonicalisation,
    # another question's answer) means another row's facts, read under this
    # row's round, that would be briefed under that row's; they are dropped.
    subject = hop.get("subject")
    subject = subject if isinstance(subject, str) and ID_RE.match(subject) else ""
    if not subject:
        park("in_facts without an object subject -- dropped")
    if bundle is not None and bundle.get("subject") != subject:
        sys.stderr.write("objects/push: the answer for %s names another subject (%r) -- "
                         "its facts are dropped\n" % (subject, bundle.get("subject")))
        bundle = None
    refused = str(hop.get("error_code") or hop.get("reject_reason") or "")
    if refused or bundle is None:
        # A refusal (GH #948: `missing_audience`, `invalid_input`,
        # `store_refused`; memory's recall names it on `hop.reject_reason`) is
        # no news about the facts: the stored ones stand and the brief is
        # rendered from them.
        sys.stderr.write("objects/push: memory gave no facts for %s (%s)\n"
                         % (subject, refused or "an answer without a bundle"))
    c = {"id": subject, "facts": None if (refused or bundle is None) else facts_of(bundle)}
    emit([store([("h", {"operation": "select", "table": "objects", "columns": COLS,
                        "where": {"id": subject}, "order_by": [{"col": "rev", "dir": "desc"}],
                        "limit": 1}),
                  ("p", {"operation": "select", "table": "pushes",
                         "columns": ["id", "brief_hash", "alias_hash", "facts", "version"],
                         "where": {"id": subject}, "limit": 1})], "facts-read", c)])

if lane == "alias_ack":
    # Only `alias` and `error_code` of a refusal are read. Its `canonical` (the
    # id that holds the alias, possibly a row of another round) is never
    # used, not even in the log line (GH #951).
    other = [{"alias": str(r.get("alias") or ""), "error_code": str(r.get("error_code") or "")}
             for r in (d.get("refused") or []) if isinstance(r, dict)
             and str(r.get("error_code") or "") != "alias_taken"]
    if hop.get("error_code"):
        other.append({"error_code": str(hop.get("error_code"))})
    if other:
        sys.stderr.write("objects/push: memory refused aliases of %s: %s\n"
                         % (str(hop.get("alias_tag") or "?"),
                            json.dumps(other, ensure_ascii=False, sort_keys=True)))
    # An entry `store_refused` is a refused closing read (OR-BC-75); binding
    # the same spelling to the same id again is idempotent, so exactly those
    # spellings go again, at most ALIAS_RETRIES times. Nothing else leaves.
    oid, _, tries = str(hop.get("alias_tag") or "").partition("#r")
    tries = int(tries) if re.fullmatch(r"[0-9]{1,2}", tries) else 0
    again = [str(r["alias"]) for r in (d.get("refused") or []) if isinstance(r, dict)
             and r.get("error_code") == "store_refused" and isinstance(r.get("alias"), str)
             and r["alias"]][:ALIASES_MAX]
    if again and ID_RE.match(oid) and tries < ALIAS_RETRIES:
        emit([{"header": {"route": "alias", "alias_tag": "%s#r%d" % (oid, tries + 1)},
               "aliases": [{"alias": a, "canonical": oid} for a in again],
               "force": False, "messages": []}])
    park()

if lane == "rendered":
    c = d.get("carry") if isinstance(d.get("carry"), dict) else {}
    row = c.get("row") if isinstance(c.get("row"), dict) else {}
    old = c.get("pushed") if isinstance(c.get("pushed"), dict) else None
    facts = c.get("facts") if isinstance(c.get("facts"), list) else []
    bh, ah = brief_hash(row, facts), alias_hash(row)
    out = []
    if not old or old.get("brief_hash") != bh:
        out.append(candidate(row, str(d.get("text") or "")))
    if not old or old.get("alias_hash") != ah:
        out.extend(alias_msgs(row))
    if not out:
        park()
    stamp = now()
    vals = {"brief_hash": bh, "alias_hash": ah, "facts": json.dumps(facts, ensure_ascii=False),
            "version": v12(row["id"], row["rev"]), "at": stamp}
    if old is None:
        op = {"operation": "insert", "table": "pushes", "row": dict(vals, id=row["id"])}
    else:
        op = {"operation": "update", "table": "pushes", "set": vals,
              "where": {"id": row["id"], "brief_hash": str(old.get("brief_hash") or ""),
                        "alias_hash": str(old.get("alias_hash") or "")}}
    emit([store([("m", op)], "mark", {"id": row["id"], "out": out})])

if lane:
    park("unknown lane %r -- dropped" % lane)
if not hop.get("operation"):
    park("a message with neither a lane nor a store answer -- dropped")

c = loads(ctx.get("cur_call"), {})
lg = legs(d)

if phase == "facts-read":
    head = (rows_of(lg.get("h")) or [None])[0]
    if head is None or head.get("state") != "active":
        park()
    pushed = (rows_of(lg.get("p")) or [None])[0]
    facts = c.get("facts")
    if facts is None:
        facts = loads((pushed or {}).get("facts"), [])
    emit([{"header": {"route": "brief_render", "reply_cell": ME},
           "row": head, "facts": facts,
           "carry": {"row": head, "facts": facts, "pushed": pushed}}])

if phase == "mark":
    leg = lg.get("m") or {}
    if leg.get("error_code") or int(leg.get("rows") or 0) < 1:
        # Another push of the same news won the compare-and-set: it went out.
        park()
    emit(c.get("out") or [])

if phase == "reset":
    park()

park("unknown phase %r -- dropped" % phase)
